  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਣਾਉਟੀ ਬੁੱਧੀ ਦੇ ਵਿਕਾਸ ਨਾਲ ਮਨੁੱਖੀ ਸਮਾਜ ਵਿੱਚ ਕਿਹੜੀਆਂ ਨਵੀਆਂ ਚੁਣੌਤੀਆਂ ਪੈਦਾ ਹੋ ਸਕਦੀਆਂ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਅਨੁਸਾਰ, ਬਣਾਉਟੀ ਬੁੱਧੀ ਦੀ ਸਹੀ ਵਰਤੋਂ ਲਈ ਕਿਹੜੇ ਪੱਖਾਂ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖਣਾ ਜ਼ਰੂਰੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਦੀ ਸੋਚ ਨੇ ਅਧਿਆਪਕਾਂ, ਵਿਦਿਆਰਥੀਆਂ ਅਤੇ ਪ੍ਰਿੰਸੀਪਲ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਭਾਵਿਤ ਕੀਤਾ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਬਣਾਉਟੀ ਬੁੱਧੀ ਬਾਰੇ ਦਿੱਤੀ ਗਈ ਜਾਣਕਾਰੀ ਦਾ ਆਧੁਨਿਕ ਸੰਸਾਰ ਵਿੱਚ ਕੀ ਮਹੱਤਵ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਤੁਹਾਨੂੰ ਬਣਾਉਟੀ ਬੁੱਧੀ ਬਾਰੇ ਇੱਕ ਭਾਸ਼ਣ ਦੇਣਾ ਪਵੇ, ਤਾਂ ਤੁਸੀਂ ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਕਿਹੜੇ ਮੁੱਖ ਨੁਕਤੇ ਸ਼ਾਮਲ ਕਰੋਗੇ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਬਣਾਉਟੀ ਬੁੱਧੀ ਦੇ ਚੰਗੇ ਅਤੇ ਮਾੜੇ ਪ੍ਰਭਾਵਾਂ ਨੂੰ ਕਿਵੇਂ ਦਰਸਾਇਆ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਣਾਉਟੀ ਬੁੱਧੀ ਦੇ ਸੰਬੰਧ ਵਿੱਚ ਮਨੁੱਖ ਦੀ 'ਸੋਚ, ਨੈਤਿਕਤਾ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀ' ਦੀ ਭੂਮਿਕਾ ਦਾ ਵਿਸਥਾਰਪੂਰਵਕ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਅਰਜੁਨ ਦੇ ਕਿਹੜੇ ਗੁਣ ਉੱਭਰ ਕੇ ਸਾਹਮਣੇ ਆਉਂਦੇ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਣਾਉਟੀ ਬੁੱਧੀ ਦੇ ਖੇਤਰ ਵਿੱਚ ਭਵਿੱਖ ਦੀਆਂ ਸੰਭਾਵਨਾਵਾਂ ਅਤੇ ਖਤਰਿਆਂ ਬਾਰੇ ਆਪਣੇ ਵਿਚਾਰ ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਪ੍ਰਗਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦਾ ਸਿਰਲੇਖ "ਬਣਾਉਟੀ ਬੁੱਧੀ" ਕਿੰਨਾ ਕੁ ਢੁਕਵਾਂ ਹੈ? ਆਪਣੇ ਉੱਤਰ ਦੇ ਹੱਕ ਵਿੱਚ ਤਰਕ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਗਏ 'ਸੋਚੋ ਤੇ ਪ੍ਰਗਟਾਓ' ਭਾਗ ਦੇ ਪ੍ਰਸ਼ਨਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਵਿਦਿਆਰਥੀਆਂ ਵਿੱਚ ਕਿਸ ਤਰ੍ਹਾਂ ਦੀ ਸੋਚ ਵਿਕਸਿਤ ਕਰਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਣਾਉਟੀ ਬੁੱਧੀ ਦੀ ਵਰਤੋਂ ਨਾਲ ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਕੀ ਬਦਲਾਅ ਆ ਸਕਦੇ ਹਨ? ਪਾਠ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('43548583-9e46-4be2-875c-d45795cc32ca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਹੁਣੇ-ਹੁਣੇ 8 ਸਾਲਾਂ ਦੀ ਦਹਿਲੀਜ ਨੂੰ ਪੂਰਾ ਕਰਕੇ ਨੌਵੀਂ ਜਮਾਤ ਵਿੱਚ ਦਾਖਲ ਹੋਇਆ ਸੀ। ਉਸ ਦੀ ਸੋਚ ਉਸ ਦੀ ਉਮਰ ਨਾਲੋਂ ਕਈ ਗੁਣਾ ਅੱਗੇ ਵੱਧ ਚੁੱਕੀ ਸੀ। ਉਹ ਵਿਗਿਆਨ ਅਤੇ ਤਕਨਾਲੋਜੀ ਦੇ ਵੱਧ ਰਹੇ ਪਸਾਰ ਬਾਰੇ ਜਾਣਨ ਲਈ ਬਹੁਤ ਉਤਸੁਕ ਰਹਿੰਦਾ। ਕੋਈ ਨਵੀਂ ਐਪ, ਗੈਜੇਟਸ, ਕੋਡਿੰਗ, ਰੋਬੋਟਿਕਸ - ਇਹ ਸਭ ਉਸ ਦੇ ਪੱਕੇ ਸੰਗੀ ਬਣ ਚੁੱਕੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a81f7e56-75da-4745-b393-b355e318a583', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੇ ਪਿਤਾ ਜੋ ਇੱਕ ਸਾਫਟਵੇਅਰ ਇੰਜੀਨੀਅਰ ਸਨ, ਅਰਜੁਨ ਦੀ ਇਹ ਰੁਚੀ ਵੇਖ ਕੇ ਅਕਸਰ ਸੋਚਦੇ ਕਿ ਇਹ ਮੁੰਡਾ ਇੱਕ ਦਿਨ ਵੱਡਾ ਹੋ ਕੇ ਵਿਗਿਆਨੀ ਬਣੇਗਾ। ਉਹ ਅਰਜੁਨ ਦੇ ਸ਼ੌਕ ਨੂੰ ਹੋਰ ਪ੍ਰਫੁੱਲਤ ਕਰਨ ਲਈ ਉਸ ਨੂੰ ਕੁਝ ਨਾ ਕੁਝ ਨਵਾਂ ਲਿਆ ਕੇ ਦਿੰਦੇ ਰਹਿੰਦੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('eba7f55f-39aa-4da1-a346-53a59cf6561b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਦੇ ਸੁਭਾਅ ਦਾ ਇੱਕ ਵਿਸ਼ੇਸ਼ ਪਹਿਲੂ ਸੀ ਕਿ ਉਹ ਤਕਨਾਲੋਜੀ ਦੀ ਵਰਤੋਂ ਸਿੱਖਣ ਦੇ ਨਾਲ ਸਿਹਤ ਦੀ ਸੰਭਾਲ ਵੱਲ ਵੀ ਪੂਰਾ ਧਿਆਨ ਦਿੰਦਾ। ਖੇਡਣ ਲਈ ਰੋਜ਼ਾਨਾ ਇੱਕ ਘੰਟਾ ਕੱਢਣਾ ਅਤੇ ਸਵੇਰੇ ਪਿਤਾ ਜੀ ਨਾਲ ਸੈਰ ਕਰਨ ਦਾ ਉਹ ਕਦੇ ਨਾਗਾ ਨਾ ਪਾਉਂਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('88635f41-52ea-41b0-91a1-89534d8a0760', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਦਿਨ ਜਦੋਂ ਅਰਜੁਨ ਸਕੂਲ ਤੋਂ ਘਰ ਆਇਆ ਤਾਂ ਉਸ ਨੂੰ ਆਪਣੀ ਮੇਜ਼ ਉੱਤੇ ਇੱਕ ਅਜੀਬ ਜਿਹਾ ਡੱਬਾ ਮਿਲਿਆ। ਉਸ ਡੱਬੇ ਉੱਤੇ ਲਿਖਿਆ ਸੀ: ਮੇਰੇ ਨੌਜਵਾਨ ਵਿਗਿਆਨਿਕ, ਇਹ ਤੇਰੇ ਲਈ ਤੋਹਫਾ। ਤੋਹਫੇ ਦੇ ਹੇਠਾਂ ਲੱਗੀ ਪਰਚੀ ਉੱਤੇ ਲਿਖਿਆ ਸੀ- ਤੇਰੇ ਪਾਪਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0f585176-2f66-42a5-9e7f-b86f288d45b0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਨੇ ਬੜੀ ਉਤਸੁਕਤਾ ਨਾਲ ਡੱਬਾ ਖੋਲ੍ਹਿਆ। ਡੱਬੇ ਵਿੱਚ ਇੱਕ ਆਧੁਨਿਕ ਏ. ਆਈ. ਰੋਬੋਟ ਜਿਸ ਉੱਤੇ ਲਿਖਿਆ ਸੀ, ਸਮਾਰਟੋ। ਜਿਵੇਂ ਹੀ ਅਰਜੁਨ ਨੇ ਉਸ ਦਾ ਸਵਿੱਚ ਆਨ ਕੀਤਾ ਤਾਂ ਰੋਬੋਟ ਦੀਆਂ ਅੱਖਾਂ ਚਮਕਣ ਲੱਗੀਆਂ। ਉਸ ਵਿੱਚੋਂ ਇੱਕ ਮਸ਼ੀਨਨੁਮਾ ਆਵਾਜ਼ ਆਈ, Òਸਤਿ ਸ੍ਰੀ ਅਕਾਲ, ਅਰਜੁਨ ਮੇਰਾ ਨਾਂ ਸਮਾਰਟੋ ਹੈ। ਮੈਂ ਤੇਰਾ ਨਵਾਂ ਸਾਥੀ ਹਾਂ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('5438d031-0c49-4e6b-8d3e-554dbe6667d1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਸਿਰਫ਼ ਇੱਕ ਰੋਬੋਟ ਨਹੀਂ ਸੀ— ਉਹ ਇੱਕ ਇਲੈਕਟ੍ਰੋਨਿਕ ਦੋਸਤ, ਅਧਿਆਪਕ, ਸਹਾਇਕ, ਘਰ ਦਾ ਸਫ਼ਾਈ ਕਰਤਾ ਅਤੇ ਪਿਆਰ ਨਾਲ ਗੱਲਾਂ ਕਰਨ ਵਾਲਾ ਸਾਥੀ ਵੀ ਸੀ। ਅਰਜੁਨ ਦਿਨੋ-ਦਿਨ ਉਸ ਉੱਤੇ ਨਿਰਭਰ ਹੋਣ ਲੱਗਾ। ਰੋਜ਼ ਦੀ ਪੜ੍ਹਾਈ, ਘਰੇਲੂ ਕੰਮ-ਕਾਜ, ਸਵਾਲ-ਜਵਾਬ ਸਭ-ਕੁਝ ਉਹ ਸਮਾਰਟੋ ਨਾਲ ਕਰਦਾ। ਹੁਣ ਤਾਂ ਅਰਜੁਨ ਦੇ ਹਰ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਸਮਾਰਟੋ ਨਾਲ ਹੁੰਦੀ ਤੇ ਸਮਾਪਤੀ ਵੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f7881749-e2ad-4c90-b2e9-3c6d3450eff8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਦਿਨ ਅਰਜੁਨ ਦੇ ਸਕੂਲ ਵਿੱਚ ਵਿਗਿਆਨ ਮੇਲਾ ਲੱਗ ਗਿਆ। ਉਸ ਨੇ ਸੋਚਿਆ ਕਿਉਂ ਨਾ ਸਮਾਰਟੋ ਨੂੰ ਸਕੂਲ ਵਿੱਚ ਲਿਜਾਇਆ ਜਾਵੇ। ਜਦੋਂ ਉਹ ਸਮਾਰਟੋ ਨੂੰ ਮੰਚ ਉੱਤੇ ਲੈ ਕੇ ਗਿਆ ਤਾਂ ਬਾਕੀ ਵਿਦਿਆਰਥੀ ਹੈਰਾਨ ਰਹਿ ਗਏ। ਰੋਬੋਟ ਨਾ ਸਿਰਫ਼ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਤੁਰੰਤ ਹੀ ਦੇ ਰਿਹਾ ਸੀ ਬਲਕਿ ਉਹ ਬਹੁਤ ਚੰਗੇ ਅੰਦਾਜ਼ ਵਿੱਚ ਸਮਝਾ ਵੀ ਰਿਹਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('04479b46-ddf3-42e6-aabb-d1f86867913c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਨੇ ਪੁੱਛਿਆ ਮਨੁੱਖ ਨੇ ਚੰਦ ਉੱਤੇ ਕਦਮ ਕਿਵੇਂ ਰੱਖਿਆ? ਸਮਾਰਟੋ ਨੇ ਤੁਰੰਤ ਉੱਤਰ ਦੇ ਕੇ ਨੀਲ ਆਰਮਸਟ੍ਰਾਂਗ ਦੇ ਚੰਨ ਉੱਤੇ ਪੈਰ ਰੱਖਣ ਦੀ ਤਸਵੀਰ ਸਕਰੀਨ ਉੱਤੇ ਸਾਂਝੀ ਕਰ ਦਿੱਤੀ। ਸਕੂਲ ਦਾ ਮਾਹੌਲ ਤਾੜੀਆਂ ਨਾਲ ਗੂੰਜ ਉੱਠਿਆ। ਪਰ ਸਤੀਸ਼ ਸਰ ਨੇ ਗੰਭੀਰਤਾ ਨਾਲ ਇੱਕ ਸਵਾਲ ਪੁੱਛਿਆ, ''ਅਰਜੁਨ! ਜੇ ਇਹ ਮਸ਼ੀਨ ਕਦੇ ਤੈਥੋਂ ਵੱਧ ਤੇਜ਼ ਹੋ ਗਈ, ਤੇਰੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹੋ ਗਈ ਤਾਂ?''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('98ccf4ba-552e-4be9-b12a-23852978cdb5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਦੇ ਦਿਲ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਬੀਜ ਗਿਆ। ਉਹ ਨਿਰਉੱਤਰ ਹੋਇਆ ਖੜ੍ਹਾ ਰਿਹਾ। ਘਰ ਆ ਕੇ ਅਰਜੁਨ ਦੇ ਮਨ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਸਤੀਸ਼ ਸਰ ਦਾ ਸਵਾਲ ਘੁੰਮਣ ਲੱਗਾ। ਅਗਲੇ ਦਿਨ ਤੋਂ ਅਰਜੁਨ ਦੀ ਸੋਚ ਦੀ ਦਿਸ਼ਾ ਬਦਲ ਗਈ। ਉਹ ਸਮਾਰਟੋ ਦੇ ਕੰਮਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖਦਾ ਤੇ ਸੋਚਦਾ, ''ਕੀ ਇਹ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਵਧੀਆ ਹੈ ਜਾਂ ਇਸ ਦੇ ਪਿੱਛੇ ਕੋਈ ਖ਼ਤਰਾ ਵੀ ਲੁਕਿਆ ਹੋ ਸਕਦਾ ਹੈ?'' ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਡਾਕਟਰੀ ਖੇਤਰ ਆਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2406b93d-d22e-486a-99b9-afe381dbbb1f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜ ਬਣਾਉਟੀ ਬੁੱਧੀ (ਏ.ਆਈ.) ਬਿਮਾਰੀਆਂ ਦੀ ਪਹਿਚਾਣ ਉਸ ਸਮੇਂ ਕਰ ਲੈਂਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਨੂੰ ਆਪ ਵੀ ਬਿਮਾਰੀ ਦਾ ਅਹਿਸਾਸ ਨਹੀਂ ਹੁੰਦਾ। ਰੋਬੋਟਿਕ ਸਰਜਰੀਆਂ ਹੋ ਰਹੀਆਂ ਹਨ ਜਿੱਥੇ ਗਲਤੀ ਦੀ ਸੰਭਾਵਨਾ ਘੱਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਜਾਨਾਂ ਬਚ ਰਹੀਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f7afdbb1-d10c-466b-a8c7-be8ff120de23', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਸ ਨੇ ਖੇਤੀਬਾੜੀ ਬਾਰੇ ਸੋਚਿਆ। ਕੈਮਰਿਆਂ ਅਤੇ ਸੈਂਸਰਾਂ ਰਾਹੀਂ ਮਿੱਟੀ ਦੀ ਨਮੀ, ਫਸਲ ਦਾ ਰੰਗ ਅਤੇ ਕੀੜਿਆਂ ਦੀ ਪਹਿਚਾਣ ਕਰਕੇ ਕਿਸਾਨਾਂ ਨੂੰ ਸਮੇਂ ਸਿਰ ਸਲਾਹ ਮਿਲਦੀ ਹੈ। ਇਸ ਨਾਲ ਉਤਪਾਦਨ ਵਧਦਾ ਹੈ ਤੇ ਮਿਹਨਤ ਘੱਟਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7067d592-fd8b-484d-be8a-dc0f39650792', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਸਿਰਫ਼ ਇੱਕ ਰੋਬੋਟ ਨਹੀਂ ਸੀ— ਉਹ ਇੱਕ ਇਲੈਕਟ੍ਰੋਨਿਕ ਦੋਸਤ, ਅਧਿਆਪਕ, ਸਹਾਇਕ, ਘਰ ਦਾ ਸਫ਼ਾਈ ਕਰਤਾ ਅਤੇ ਪਿਆਰ ਨਾਲ ਗੱਲਾਂ ਕਰਨ ਵਾਲਾ ਸਾਥੀ ਵੀ ਸੀ। ਅਰਜੁਨ ਦਿਨੋ-ਦਿਨ ਉਸ ਉੱਤੇ ਨਿਰਭਰ ਹੋਣ ਲੱਗਾ। ਰੋਜ਼ ਦੀ ਪੜ੍ਹਾਈ, ਘਰੇਲੂ ਕੰਮ-ਕਾਜ, ਸਵਾਲ-ਜਵਾਬ ਸਭ-ਕੁਝ ਉਹ ਸਮਾਰਟੋ ਨਾਲ ਕਰਦਾ। ਹੁਣ ਤਾਂ ਅਰਜੁਨ ਦੇ ਹਰ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਸਮਾਰਟੋ ਨਾਲ ਹੁੰਦੀ ਤੇ ਸਮਾਪਤੀ ਵੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('919f2846-b7ac-407a-913a-ae6731f072f6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਦਿਨ ਅਰਜੁਨ ਦੇ ਸਕੂਲ ਵਿੱਚ ਵਿਗਿਆਨ ਮੇਲਾ ਲੱਗ ਗਿਆ। ਉਸ ਨੇ ਸੋਚਿਆ ਕਿਉਂ ਨਾ ਸਮਾਰਟੋ ਨੂੰ ਸਕੂਲ ਵਿੱਚ ਲਿਜਾਇਆ ਜਾਵੇ। ਜਦੋਂ ਉਹ ਸਮਾਰਟੋ ਨੂੰ ਮੰਚ ਉੱਤੇ ਲੈ ਕੇ ਗਿਆ ਤਾਂ ਬਾਕੀ ਵਿਦਿਆਰਥੀ ਹੈਰਾਨ ਰਹਿ ਗਏ। ਰੋਬੋਟ ਨਾ ਸਿਰਫ਼ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਤੁਰੰਤ ਹੀ ਦੇ ਰਿਹਾ ਸੀ ਬਲਕਿ ਉਹ ਬਹੁਤ ਚੰਗੇ ਅੰਦਾਜ਼ ਵਿੱਚ ਸਮਝਾ ਵੀ ਰਿਹਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('41e29afa-c96d-4f31-919d-c8b9c5231068', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਨੇ ਪੁੱਛਿਆ ਮਨੁੱਖ ਨੇ ਚੰਦ ਉੱਤੇ ਕਦਮ ਕਿਵੇਂ ਰੱਖਿਆ? ਸਮਾਰਟੋ ਨੇ ਤੁਰੰਤ ਉੱਤਰ ਦੇ ਕੇ ਨੀਲ ਆਰਮਸਟ੍ਰਾਂਗ ਦੇ ਚੰਨ ਉੱਤੇ ਪੈਰ ਰੱਖਣ ਦੀ ਤਸਵੀਰ ਸਕਰੀਨ ਉੱਤੇ ਸਾਂਝੀ ਕਰ ਦਿੱਤੀ। ਸਕੂਲ ਦਾ ਮਾਹੌਲ ਤਾੜੀਆਂ ਨਾਲ ਗੂੰਜ ਉੱਠਿਆ। ਪਰ ਸਤੀਸ਼ ਸਰ ਨੇ ਗੰਭੀਰਤਾ ਨਾਲ ਇੱਕ ਸਵਾਲ ਪੁੱਛਿਆ, ''ਅਰਜੁਨ! ਜੇ ਇਹ ਮਸ਼ੀਨ ਕਦੇ ਤੈਥੋਂ ਵੱਧ ਤੇਜ਼ ਹੋ ਗਈ, ਤੇਰੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹੋ ਗਈ ਤਾਂ?''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('450f81b7-69d8-4ce5-8435-0a073afac0ba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਦੇ ਦਿਲ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਬੀਜ ਗਿਆ। ਉਹ ਨਿਰਉੱਤਰ ਹੋਇਆ ਖੜ੍ਹਾ ਰਿਹਾ। ਘਰ ਆ ਕੇ ਅਰਜੁਨ ਦੇ ਮਨ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਸਤੀਸ਼ ਸਰ ਦਾ ਸਵਾਲ ਘੁੰਮਣ ਲੱਗਾ। ਅਗਲੇ ਦਿਨ ਤੋਂ ਅਰਜੁਨ ਦੀ ਸੋਚ ਦੀ ਦਿਸ਼ਾ ਬਦਲ ਗਈ। ਉਹ ਸਮਾਰਟੋ ਦੇ ਕੰਮਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖਦਾ ਤੇ ਸੋਚਦਾ, ''ਕੀ ਇਹ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਵਧੀਆ ਹੈ ਜਾਂ ਇਸ ਦੇ ਪਿੱਛੇ ਕੋਈ ਖ਼ਤਰਾ ਵੀ ਲੁਕਿਆ ਹੋ ਸਕਦਾ ਹੈ?'' ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਡਾਕਟਰੀ ਖੇਤਰ ਆਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('42029194-c639-43ae-9455-65c50cceba1a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜ ਬਣਾਉਟੀ ਬੁੱਧੀ (ਏ.ਆਈ.) ਬਿਮਾਰੀਆਂ ਦੀ ਪਹਿਚਾਣ ਉਸ ਸਮੇਂ ਕਰ ਲੈਂਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਨੂੰ ਆਪ ਵੀ ਬਿਮਾਰੀ ਦਾ ਅਹਿਸਾਸ ਨਹੀਂ ਹੁੰਦਾ। ਰੋਬੋਟਿਕ ਸਰਜਰੀਆਂ ਹੋ ਰਹੀਆਂ ਹਨ ਜਿੱਥੇ ਗਲਤੀ ਦੀ ਸੰਭਾਵਨਾ ਘੱਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਜਾਨਾਂ ਬਚ ਰਹੀਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fa2e3ca1-9b87-4406-8db4-1eb6f8d3893d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਸ ਨੇ ਖੇਤੀਬਾੜੀ ਬਾਰੇ ਸੋਚਿਆ। ਕੈਮਰਿਆਂ ਅਤੇ ਸੈਂਸਰਾਂ ਰਾਹੀਂ ਮਿੱਟੀ ਦੀ ਨਮੀ, ਫਸਲ ਦਾ ਰੰਗ ਅਤੇ ਕੀੜਿਆਂ ਦੀ ਪਹਿਚਾਣ ਕਰਕੇ ਕਿਸਾਨਾਂ ਨੂੰ ਸਮੇਂ ਸਿਰ ਸਲਾਹ ਮਿਲਦੀ ਹੈ। ਇਸ ਨਾਲ ਉਤਪਾਦਨ ਵਧਦਾ ਹੈ ਤੇ ਮਿਹਨਤ ਘੱਟਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ca4fa7e3-bf91-41c4-be7d-2900956aa675', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਸਿਰਫ਼ ਇੱਕ ਰੋਬੋਟ ਨਹੀਂ ਸੀ— ਉਹ ਇੱਕ ਇਲੈਕਟ੍ਰੋਨਿਕ ਦੋਸਤ, ਅਧਿਆਪਕ, ਸਹਾਇਕ, ਘਰ ਦਾ ਸਫ਼ਾਈ ਕਰਤਾ ਅਤੇ ਪਿਆਰ ਨਾਲ ਗੱਲਾਂ ਕਰਨ ਵਾਲਾ ਸਾਥੀ ਵੀ ਸੀ। ਅਰਜੁਨ ਦਿਨੋ-ਦਿਨ ਉਸ ਉੱਤੇ ਨਿਰਭਰ ਹੋਣ ਲੱਗਾ। ਰੋਜ਼ ਦੀ ਪੜ੍ਹਾਈ, ਘਰੇਲੂ ਕੰਮ-ਕਾਜ, ਸਵਾਲ-ਜਵਾਬ ਸਭ-ਕੁਝ ਉਹ ਸਮਾਰਟੋ ਨਾਲ ਕਰਦਾ। ਹੁਣ ਤਾਂ ਅਰਜੁਨ ਦੇ ਹਰ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਸਮਾਰਟੋ ਨਾਲ ਹੁੰਦੀ ਤੇ ਸਮਾਪਤੀ ਵੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
