  ('52f1cd8b-a8d9-4c9a-98aa-f9bd6b7f1c01', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਸਿਰਫ਼ ਇੱਕ ਰੋਬੋਟ ਨਹੀਂ ਸੀ— ਉਹ ਇੱਕ ਇਲੈਕਟ੍ਰੋਨਿਕ ਦੋਸਤ, ਅਧਿਆਪਕ, ਸਹਾਇਕ, ਘਰ ਦਾ ਸਫ਼ਾਈ ਕਰਤਾ ਅਤੇ ਪਿਆਰ ਨਾਲ ਗੱਲਾਂ ਕਰਨ ਵਾਲਾ ਸਾਥੀ ਵੀ ਸੀ। ਅਰਜੁਨ ਦਿਨੋ-ਦਿਨ ਉਸ ਉੱਤੇ ਨਿਰਭਰ ਹੋਣ ਲੱਗਾ। ਰੋਜ਼ ਦੀ ਪੜ੍ਹਾਈ, ਘਰੇਲੂ ਕੰਮ-ਕਾਜ, ਸਵਾਲ-ਜਵਾਬ ਸਭ-ਕੁਝ ਉਹ ਸਮਾਰਟੋ ਨਾਲ ਕਰਦਾ। ਹੁਣ ਤਾਂ ਅਰਜੁਨ ਦੇ ਹਰ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਸਮਾਰਟੋ ਨਾਲ ਹੁੰਦੀ ਤੇ ਸਮਾਪਤੀ ਵੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('199c9730-091a-4432-9dea-e1ff3b1418fe', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਦਿਨ ਅਰਜੁਨ ਦੇ ਸਕੂਲ ਵਿੱਚ ਵਿਗਿਆਨ ਮੇਲਾ ਲੱਗ ਗਿਆ। ਉਸ ਨੇ ਸੋਚਿਆ ਕਿਉਂ ਨਾ ਸਮਾਰਟੋ ਨੂੰ ਸਕੂਲ ਵਿੱਚ ਲਿਜਾਇਆ ਜਾਵੇ। ਜਦੋਂ ਉਹ ਸਮਾਰਟੋ ਨੂੰ ਮੰਚ ਉੱਤੇ ਲੈ ਕੇ ਗਿਆ ਤਾਂ ਬਾਕੀ ਵਿਦਿਆਰਥੀ ਹੈਰਾਨ ਰਹਿ ਗਏ। ਰੋਬੋਟ ਨਾ ਸਿਰਫ਼ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਤੁਰੰਤ ਹੀ ਦੇ ਰਿਹਾ ਸੀ ਬਲਕਿ ਉਹ ਬਹੁਤ ਚੰਗੇ ਅੰਦਾਜ਼ ਵਿੱਚ ਸਮਝਾ ਵੀ ਰਿਹਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f2f86418-cabc-4abe-b6af-f4d7b588c5bb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਨੇ ਪੁੱਛਿਆ ਮਨੁੱਖ ਨੇ ਚੰਦ ਉੱਤੇ ਕਦਮ ਕਿਵੇਂ ਰੱਖਿਆ? ਸਮਾਰਟੋ ਨੇ ਤੁਰੰਤ ਉੱਤਰ ਦੇ ਕੇ ਨੀਲ ਆਰਮਸਟ੍ਰਾਂਗ ਦੇ ਚੰਨ ਉੱਤੇ ਪੈਰ ਰੱਖਣ ਦੀ ਤਸਵੀਰ ਸਕਰੀਨ ਉੱਤੇ ਸਾਂਝੀ ਕਰ ਦਿੱਤੀ। ਸਕੂਲ ਦਾ ਮਾਹੌਲ ਤਾੜੀਆਂ ਨਾਲ ਗੂੰਜ ਉੱਠਿਆ। ਪਰ ਸਤੀਸ਼ ਸਰ ਨੇ ਗੰਭੀਰਤਾ ਨਾਲ ਇੱਕ ਸਵਾਲ ਪੁੱਛਿਆ, ''ਅਰਜੁਨ! ਜੇ ਇਹ ਮਸ਼ੀਨ ਕਦੇ ਤੈਥੋਂ ਵੱਧ ਤੇਜ਼ ਹੋ ਗਈ, ਤੇਰੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹੋ ਗਈ ਤਾਂ?''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('15db3106-1a53-42d2-a5f1-bd423c4037ad', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਦੇ ਦਿਲ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਬੀਜ ਗਿਆ। ਉਹ ਨਿਰਉੱਤਰ ਹੋਇਆ ਖੜ੍ਹਾ ਰਿਹਾ। ਘਰ ਆ ਕੇ ਅਰਜੁਨ ਦੇ ਮਨ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਸਤੀਸ਼ ਸਰ ਦਾ ਸਵਾਲ ਘੁੰਮਣ ਲੱਗਾ। ਅਗਲੇ ਦਿਨ ਤੋਂ ਅਰਜੁਨ ਦੀ ਸੋਚ ਦੀ ਦਿਸ਼ਾ ਬਦਲ ਗਈ। ਉਹ ਸਮਾਰਟੋ ਦੇ ਕੰਮਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖਦਾ ਤੇ ਸੋਚਦਾ, ''ਕੀ ਇਹ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਵਧੀਆ ਹੈ ਜਾਂ ਇਸ ਦੇ ਪਿੱਛੇ ਕੋਈ ਖ਼ਤਰਾ ਵੀ ਲੁਕਿਆ ਹੋ ਸਕਦਾ ਹੈ?'' ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਡਾਕਟਰੀ ਖੇਤਰ ਆਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ba299961-a58e-440c-b68f-05f1b1bf0f76', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜ ਬਣਾਉਟੀ ਬੁੱਧੀ (ਏ.ਆਈ.) ਬਿਮਾਰੀਆਂ ਦੀ ਪਹਿਚਾਣ ਉਸ ਸਮੇਂ ਕਰ ਲੈਂਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਨੂੰ ਆਪ ਵੀ ਬਿਮਾਰੀ ਦਾ ਅਹਿਸਾਸ ਨਹੀਂ ਹੁੰਦਾ। ਰੋਬੋਟਿਕ ਸਰਜਰੀਆਂ ਹੋ ਰਹੀਆਂ ਹਨ ਜਿੱਥੇ ਗਲਤੀ ਦੀ ਸੰਭਾਵਨਾ ਘੱਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਜਾਨਾਂ ਬਚ ਰਹੀਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('89d18f84-d71c-4f9c-b4be-09a113da5a26', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('bc2433fe-d859-41ea-81e9-c107111b26b7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9b9ddf3f-e892-45a7-95dc-4015c6e18eee', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ। ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('45e753a6-60df-4d58-8344-61e0e792019a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('81d23b6c-53e6-4ab1-9274-bd06f14168c9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜੀ ਚੁਣੌਤੀ ਸੁਰੱਖਿਆ ਦੀ ਸੀ। ਜੇ ਏ.ਆਈ. ਹਥਿਆਰਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਤਾਂ ਜੰਗਾਂ ਹੋਰ ਵੀ ਖੂਨੀ ਤੇ ਵਿਨਾਸ਼ਕਾਰੀ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸੋਚੋ, ਜੇ ਬਿਨਾਂ ਮਨੁੱਖੀ ਦਖਲ ਦੇ ਹੀ ਰੋਬੋਟ ਫੌਜ ਲੜਾਈ ਲੜਨ ਲੱਗੇ ਤਾਂ ਨਤੀਜੇ ਕਿੰਨੇ ਖਤਰਨਾਕ ਹੋਣਗੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d6b18093-2a9b-4101-867f-ade2d92f7c05', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ ਖਤਰਾ ਨੈਤਿਕਤਾ ਨਾਲ ਸੀ। (ਏ.ਆਈ.) ਦੇ ਕੋਲ ਦਿਲ ਨਹੀਂ ਹੁੰਦਾ। ਉਹ ਫੈਸਲੇ ਸਿਰਫ ਡਾਟਾ ਦੇ ਆਧਾਰ ਉੱਤੇ ਕਰਦੀ ਹੈ ਪਰ ਮਨੁੱਖੀ ਜੀਵਨ ਸਿਰਫ ਅੰਕੜਿਆਂ ਨਾਲ ਨਹੀਂ, ਭਾਵਨਾਵਾਂ ਨਾਲ ਵੀ ਚੱਲਦਾ ਹੈ। ਜੇ ਕੋਈ ਰੋਬੋਟ ਜੱਜ ਬਣ ਜਾਵੇ ਤਾਂ ਕੀ ਉਹ ਇਨਸਾਫ ਕਰ ਸਕੇਗਾ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('91392f95-0a6e-40dd-a3d6-94b377ff3327', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('966dba93-96e2-4bdf-9c14-276652eebf52', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7503fff1-5577-43b5-9f83-b8ea628217a7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f11e12ed-2e38-476e-b6aa-2959ac84a42a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ। ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0221bfce-da97-44f9-894b-3aaa94d2e49b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ। ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ। ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
