  ('2e530e1d-0274-4ed6-b884-54ec62aa7135', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ। ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4d6bdd0c-d080-4a83-a77e-449bbca89c3f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0dde6e74-7e68-4f8f-93fd-86d4194fceb8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ। ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ। ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b7e7e70b-eecc-4424-bd86-2828af5aefd4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ। ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ। ਦੂਜੀ ਚੁਣੌਤੀ ਸੁਰੱਖਿਆ ਦੀ ਸੀ। ਜੇ ਏ.ਆਈ. ਹਥਿਆਰਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਤਾਂ ਜੰਗਾਂ ਹੋਰ ਵੀ ਖੂਨੀ ਤੇ ਵਿਨਾਸ਼ਕਾਰੀ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸੋਚੋ, ਜੇ ਬਿਨਾਂ ਮਨੁੱਖੀ ਦਖਲ ਦੇ ਹੀ ਰੋਬੋਟ ਫੌਜ ਲੜਾਈ ਲੜਨ ਲੱਗੇ ਤਾਂ ਨਤੀਜੇ ਕਿੰਨੇ ਖਤਰਨਾਕ ਹੋਣਗੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('331a0ecd-e75a-4d5b-acbc-e475f3d1304a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ ਖਤਰਾ ਨੈਤਿਕਤਾ ਨਾਲ ਸੀ। (ਏ.ਆਈ.) ਦੇ ਕੋਲ ਦਿਲ ਨਹੀਂ ਹੁੰਦਾ। ਉਹ ਫੈਸਲੇ ਸਿਰਫ ਡਾਟਾ ਦੇ ਆਧਾਰ ਉੱਤੇ ਕਰਦੀ ਹੈ ਪਰ ਮਨੁੱਖੀ ਜੀਵਨ ਸਿਰਫ ਅੰਕੜਿਆਂ ਨਾਲ ਨਹੀਂ, ਭਾਵਨਾਵਾਂ ਨਾਲ ਵੀ ਚੱਲਦਾ ਹੈ। ਜੇ ਕੋਈ ਰੋਬੋਟ ਜੱਜ ਬਣ ਜਾਵੇ ਤਾਂ ਕੀ ਉਹ ਇਨਸਾਫ ਕਰ ਸਕੇਗਾ? ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1d817a30-680a-4b42-8433-2817276f1b16', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?' ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b978a0c7-0c0a-49c4-8f26-8bb05b62b4f3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ। ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ। ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7e5714e0-c150-424f-8fdf-2056202087e8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ। ਦੂਜੀ ਚੁਣੌਤੀ ਸੁਰੱਖਿਆ ਦੀ ਸੀ। ਜੇ ਏ.ਆਈ. ਹਥਿਆਰਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਤਾਂ ਜੰਗਾਂ ਹੋਰ ਵੀ ਖੂਨੀ ਤੇ ਵਿਨਾਸ਼ਕਾਰੀ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸੋਚੋ, ਜੇ ਬਿਨਾਂ ਮਨੁੱਖੀ ਦਖਲ ਦੇ ਹੀ ਰੋਬੋਟ ਫੌਜ ਲੜਾਈ ਲੜਨ ਲੱਗੇ ਤਾਂ ਨਤੀਜੇ ਕਿੰਨੇ ਖਤਰਨਾਕ ਹੋਣਗੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c9cfabd6-8b87-4306-8097-740e53741b7c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ ਖਤਰਾ ਨੈਤਿਕਤਾ ਨਾਲ ਸੀ। (ਏ.ਆਈ.) ਦੇ ਕੋਲ ਦਿਲ ਨਹੀਂ ਹੁੰਦਾ। ਉਹ ਫੈਸਲੇ ਸਿਰਫ ਡਾਟਾ ਦੇ ਆਧਾਰ ਉੱਤੇ ਕਰਦੀ ਹੈ ਪਰ ਮਨੁੱਖੀ ਜੀਵਨ ਸਿਰਫ ਅੰਕੜਿਆਂ ਨਾਲ ਨਹੀਂ, ਭਾਵਨਾਵਾਂ ਨਾਲ ਵੀ ਚੱਲਦਾ ਹੈ। ਜੇ ਕੋਈ ਰੋਬੋਟ ਜੱਜ ਬਣ ਜਾਵੇ ਤਾਂ ਕੀ ਉਹ ਇਨਸਾਫ ਕਰ ਸਕੇਗਾ? ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('30ad1605-fff6-41e8-a0a7-ea7dc1c93ea0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?' ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
