  ('9980b681-7218-407d-8eda-11dcc6ef8455', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ। ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
