  ('9b27cc0f-1516-4b50-8718-48d82834443f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਸੀਂ ਤਕਨੀਕ ਨੂੰ ਆਪਣੇ ਹਥਿਆਰ ਨਹੀਂ, ਆਪਣਾ ਸਾਥੀ ਬਣਾਵਾਂਗੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('db9ec61c-d052-433b-a102-888125d4ae7a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਧਿਆਪਕ, ਵਿਦਿਆਰਥੀ, ਪ੍ਰਿੰਸੀਪਲ ਸਭ ਉਸ ਦੀ ਸੋਚ 'ਤੇ ਮਾਣ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('36c02e86-4474-4600-98b3-ec203f36a96d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਵੀਂ ਤਕਨੀਕ ਸਿੱਖਣ ਵਿੱਚ ਰੁਚੀ ਪੈਦਾ ਹੋਣਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a60092ca-e056-4012-a35b-c8edc8a6b906', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤਕਨੀਕ ਦੀ ਵਰਤੋਂ ਚੰਗੇ-ਮਾੜੇ ਪੱਖਾਂ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਣੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('86cfa827-4cbd-49e5-ac56-47079cc8d72d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (N.E.P.) ਅਤੇ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ 'ਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ—$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c67bdeb0-aa19-4c03-ad61-087d15e53af7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਹੁਣੇ-ਹੁਣੇ 8 ਸਾਲਾਂ ਦੀ ਦਹਿਲੀਜ ਨੂੰ ਪੂਰਾ ਕਰਕੇ ਨੌਵੀਂ ਜਮਾਤ ਵਿੱਚ ਦਾਖਲ ਹੋਇਆ ਸੀ। ਉਸ ਦੀ ਸੋਚ ਉਸ ਦੀ ਉਮਰ ਨਾਲੋਂ ਕਈ ਗੁਣਾ ਅੱਗੇ ਵੱਧ ਚੁੱਕੀ ਸੀ। ਉਹ ਵਿਗਿਆਨ ਅਤੇ ਤਕਨਾਲੋਜੀ ਦੇ ਵੱਧ ਰਹੇ ਪਸਾਰ ਬਾਰੇ ਜਾਣਨ ਲਈ ਬਹੁਤ ਉਤਸੁਕ ਰਹਿੰਦਾ। ਕੋਈ ਨਵੀਂ ਐਪ, ਗੈਜੇਟਸ, ਕੋਡਿੰਗ, ਰੋਬੋਟਿਕਸ - ਇਹ ਸਭ ਉਸ ਦੇ ਪੱਕੇ ਸੰਗੀ ਬਣ ਚੁੱਕੇ ਸਨ। ਉਸ ਦੇ ਪਿਤਾ ਜੋ ਇੱਕ ਸਾਫਟਵੇਅਰ ਇੰਜੀਨੀਅਰ ਸਨ, ਅਰਜੁਨ ਦੀ ਇਹ ਰੁਚੀ ਵੇਖ ਕੇ ਅਕਸਰ ਸੋਚਦੇ ਕਿ ਇਹ ਮੁੰਡਾ ਇੱਕ ਦਿਨ ਵੱਡਾ ਹੋ ਕੇ ਵਿਗਿਆਨੀ ਬਣੇਗਾ। ਉਹ ਅਰਜੁਨ ਦੇ ਸ਼ੌਕ ਨੂੰ ਹੋਰ ਪ੍ਰਫੁੱਲਤ ਕਰਨ ਲਈ ਉਸ ਨੂੰ ਕੁਝ ਨਾ ਕੁਝ ਨਵਾਂ ਲਿਆ ਕੇ ਦਿੰਦੇ ਰਹਿੰਦੇ। ਅਰਜੁਨ ਦੇ ਸੁਭਾਅ ਦਾ ਇੱਕ ਵਿਸ਼ੇਸ਼ ਪਹਿਲੂ ਸੀ ਕਿ ਉਹ ਤਕਨਾਲੋਜੀ ਦੀ ਵਰਤੋਂ ਸਿੱਖਣ ਦੇ ਨਾਲ ਸਿਹਤ ਦੀ ਸੰਭਾਲ ਵੱਲ ਵੀ ਪੂਰਾ ਧਿਆਨ ਦਿੰਦਾ। ਖੇਡਣ ਲਈ ਰੋਜ਼ਾਨਾ ਇੱਕ ਘੰਟਾ ਕੱਢਣਾ ਅਤੇ ਸਵੇਰੇ ਪਿਤਾ ਜੀ ਨਾਲ ਸੈਰ ਕਰਨ ਦਾ ਉਹ ਕਦੇ ਨਾਗਾ ਨਾ ਪਾਉਂਦਾ। ਇੱਕ ਦਿਨ ਜਦੋਂ ਅਰਜੁਨ ਸਕੂਲ ਤੋਂ ਘਰ ਆਇਆ ਤਾਂ ਉਸ ਨੂੰ ਆਪਣੀ ਮੇਜ਼ ਉੱਤੇ ਇੱਕ ਅਜੀਬ ਜਿਹਾ ਡੱਬਾ ਮਿਲਿਆ। ਉਸ ਡੱਬੇ ਉੱਤੇ ਲਿਖਿਆ ਸੀ: ਮੇਰੇ ਨੌਜਵਾਨ ਵਿਗਿਆਨਿਕ, ਇਹ ਤੇਰੇ ਲਈ ਤੋਹਫਾ। ਤੋਹਫੇ ਦੇ ਹੇਠਾਂ ਲੱਗੀ ਪਰਚੀ ਉੱਤੇ ਲਿਖਿਆ ਸੀ- ਤੇਰੇ ਪਾਪਾ। ਅਰਜੁਨ ਨੇ ਬੜੀ ਉਤਸੁਕਤਾ ਨਾਲ ਡੱਬਾ ਖੋਲ੍ਹਿਆ। ਡੱਬੇ ਵਿੱਚ ਇੱਕ ਆਧੁਨਿਕ ਏ. ਆਈ. ਰੋਬੋਟ ਜਿਸ ਉੱਤੇ ਲਿਖਿਆ ਸੀ, ਸਮਾਰਟੋ। ਜਿਵੇਂ ਹੀ ਅਰਜੁਨ ਨੇ ਉਸ ਦਾ ਸਵਿੱਚ ਆਨ ਕੀਤਾ ਤਾਂ ਰੋਬੋਟ ਦੀਆਂ ਅੱਖਾਂ ਚਮਕਣ ਲੱਗੀਆਂ। ਉਸ ਵਿੱਚੋਂ ਇੱਕ ਮਸ਼ੀਨਨੁਮਾ ਆਵਾਜ਼ ਆਈ, Òਸਤਿ ਸ੍ਰੀ ਅਕਾਲ, ਅਰਜੁਨ ਮੇਰਾ ਨਾਂ ਸਮਾਰਟੋ ਹੈ। ਮੈਂ ਤੇਰਾ ਨਵਾਂ ਸਾਥੀ ਹਾਂ।ÓÓ ਦਹਿਲੀਜ - ਪ੍ਰਵੇਸ਼ ਦੁਆਰ, ਉਤਸੁਕ - ਜਾਣਨ ਦੀ ਇੱਛਾ ਰੱਖਣ ਵਾਲਾ, ਪ੍ਰਫੁੱਲਤ - ਉਤਸਾਹਿਤ ਕਰਨਾ, ਹੋਰ ਵਧਾਉਣਾ, ਮਸ਼ੀਨਨੁਮਾ - ਮਸ਼ੀਨ ਵਰਗੀ, ਸਾਥੀ - ਸੰਗੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 25, NULL),
  ('70836a7e-54a5-419c-baff-037172373c82', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਸਿਰਫ਼ ਇੱਕ ਰੋਬੋਟ ਨਹੀਂ ਸੀ— ਉਹ ਇੱਕ ਇਲੈਕਟ੍ਰੋਨਿਕ ਦੋਸਤ, ਅਧਿਆਪਕ, ਸਹਾਇਕ, ਘਰ ਦਾ ਸਫ਼ਾਈ ਕਰਤਾ ਅਤੇ ਪਿਆਰ ਨਾਲ ਗੱਲਾਂ ਕਰਨ ਵਾਲਾ ਸਾਥੀ ਵੀ ਸੀ। ਅਰਜੁਨ ਦਿਨੋ-ਦਿਨ ਉਸ ਉੱਤੇ ਨਿਰਭਰ ਹੋਣ ਲੱਗਾ। ਰੋਜ਼ ਦੀ ਪੜ੍ਹਾਈ, ਘਰੇਲੂ ਕੰਮ-ਕਾਜ, ਸਵਾਲ-ਜਵਾਬ ਸਭ-ਕੁਝ ਉਹ ਸਮਾਰਟੋ ਨਾਲ ਕਰਦਾ। ਹੁਣ ਤਾਂ ਅਰਜੁਨ ਦੇ ਹਰ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਸਮਾਰਟੋ ਨਾਲ ਹੁੰਦੀ ਤੇ ਸਮਾਪਤੀ ਵੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b6eb438b-5e46-4424-9334-2c89debf8682', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਦਿਨ ਅਰਜੁਨ ਦੇ ਸਕੂਲ ਵਿੱਚ ਵਿਗਿਆਨ ਮੇਲਾ ਲੱਗ ਗਿਆ। ਉਸ ਨੇ ਸੋਚਿਆ ਕਿਉਂ ਨਾ ਸਮਾਰਟੋ ਨੂੰ ਸਕੂਲ ਵਿੱਚ ਲਿਜਾਇਆ ਜਾਵੇ। ਜਦੋਂ ਉਹ ਸਮਾਰਟੋ ਨੂੰ ਮੰਚ ਉੱਤੇ ਲੈ ਕੇ ਗਿਆ ਤਾਂ ਬਾਕੀ ਵਿਦਿਆਰਥੀ ਹੈਰਾਨ ਰਹਿ ਗਏ। ਰੋਬੋਟ ਨਾ ਸਿਰਫ਼ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਤੁਰੰਤ ਹੀ ਦੇ ਰਿਹਾ ਸੀ ਬਲਕਿ ਉਹ ਬਹੁਤ ਚੰਗੇ ਅੰਦਾਜ਼ ਵਿੱਚ ਸਮਝਾ ਵੀ ਰਿਹਾ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('55ba6c59-75d7-460d-aba6-328102825a1d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਨੇ ਪੁੱਛਿਆ ਮਨੁੱਖ ਨੇ ਚੰਦ ਉੱਤੇ ਕਦਮ ਕਿਵੇਂ ਰੱਖਿਆ? ਸਮਾਰਟੋ ਨੇ ਤੁਰੰਤ ਉੱਤਰ ਦੇ ਕੇ ਨੀਲ ਆਰਮਸਟ੍ਰਾਂਗ ਦੇ ਚੰਨ ਉੱਤੇ ਪੈਰ ਰੱਖਣ ਦੀ ਤਸਵੀਰ ਸਕਰੀਨ ਉੱਤੇ ਸਾਂਝੀ ਕਰ ਦਿੱਤੀ। ਸਕੂਲ ਦਾ ਮਾਹੌਲ ਤਾੜੀਆਂ ਨਾਲ ਗੂੰਜ ਉੱਠਿਆ। ਪਰ ਸਤੀਸ਼ ਸਰ ਨੇ ਗੰਭੀਰਤਾ ਨਾਲ ਇੱਕ ਸਵਾਲ ਪੁੱਛਿਆ, ''ਅਰਜੁਨ! ਜੇ ਇਹ ਮਸ਼ੀਨ ਕਦੇ ਤੈਥੋਂ ਵੱਧ ਤੇਜ਼ ਹੋ ਗਈ, ਤੇਰੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹੋ ਗਈ ਤਾਂ?''$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d867964b-c5c7-42d3-bda9-de5eaa4383d0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਦੇ ਦਿਲ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਬੀਜ ਗਿਆ। ਉਹ ਨਿਰਉੱਤਰ ਹੋਇਆ ਖੜ੍ਹਾ ਰਿਹਾ। ਘਰ ਆ ਕੇ ਅਰਜੁਨ ਦੇ ਮਨ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਸਤੀਸ਼ ਸਰ ਦਾ ਸਵਾਲ ਘੁੰਮਣ ਲੱਗਾ। ਅਗਲੇ ਦਿਨ ਤੋਂ ਅਰਜੁਨ ਦੀ ਸੋਚ ਦੀ ਦਿਸ਼ਾ ਬਦਲ ਗਈ। ਉਹ ਸਮਾਰਟੋ ਦੇ ਕੰਮਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖਦਾ ਤੇ ਸੋਚਦਾ, ''ਕੀ ਇਹ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਵਧੀਆ ਹੈ ਜਾਂ ਇਸ ਦੇ ਪਿੱਛੇ ਕੋਈ ਖ਼ਤਰਾ ਵੀ ਲੁਕਿਆ ਹੋ ਸਕਦਾ ਹੈ?'' ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਡਾਕਟਰੀ ਖੇਤਰ ਆਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('684cafa1-cbe8-4d59-b33e-92571dad8f2c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜ ਬਣਾਉਟੀ ਬੁੱਧੀ (ਏ.ਆਈ.) ਬਿਮਾਰੀਆਂ ਦੀ ਪਹਿਚਾਣ ਉਸ ਸਮੇਂ ਕਰ ਲੈਂਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਨੂੰ ਆਪ ਵੀ ਬਿਮਾਰੀ ਦਾ ਅਹਿਸਾਸ ਨਹੀਂ ਹੁੰਦਾ। ਰੋਬੋਟਿਕ ਸਰਜਰੀਆਂ ਹੋ ਰਹੀਆਂ ਹਨ ਜਿੱਥੇ ਗਲਤੀ ਦੀ ਸੰਭਾਵਨਾ ਘੱਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਜਾਨਾਂ ਬਚ ਰਹੀਆਂ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('264c292e-6837-4096-87df-4b6f9f1605e7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਸ ਨੇ ਖੇਤੀਬਾੜੀ ਬਾਰੇ ਸੋਚਿਆ। ਕੈਮਰਿਆਂ ਅਤੇ ਸੈਂਸਰਾਂ ਰਾਹੀਂ ਮਿੱਟੀ ਦੀ ਨਮੀ, ਫਸਲ ਦਾ ਰੰਗ ਅਤੇ ਕੀੜਿਆਂ ਦੀ ਪਹਿਚਾਣ ਕਰਕੇ ਕਿਸਾਨਾਂ ਨੂੰ ਸਮੇਂ ਸਿਰ ਸਲਾਹ ਮਿਲਦੀ ਹੈ। ਇਸ ਨਾਲ ਉਤਪਾਦਨ ਵਧਦਾ ਹੈ ਤੇ ਮਿਹਨਤ ਘੱਟਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
