  ('34348ca1-f4d1-4b1e-a184-7e6742f2237e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਨੇ ਪੁੱਛਿਆ ਮਨੁੱਖ ਨੇ ਚੰਦ ਉੱਤੇ ਕਦਮ ਕਿਵੇਂ ਰੱਖਿਆ? ਸਮਾਰਟੋ ਨੇ ਤੁਰੰਤ ਉੱਤਰ ਦੇ ਕੇ ਨੀਲ ਆਰਮਸਟ੍ਰਾਂਗ ਦੇ ਚੰਨ ਉੱਤੇ ਪੈਰ ਰੱਖਣ ਦੀ ਤਸਵੀਰ ਸਕਰੀਨ ਉੱਤੇ ਸਾਂਝੀ ਕਰ ਦਿੱਤੀ। ਸਕੂਲ ਦਾ ਮਾਹੌਲ ਤਾੜੀਆਂ ਨਾਲ ਗੂੰਜ ਉੱਠਿਆ। ਪਰ ਸਤੀਸ਼ ਸਰ ਨੇ ਗੰਭੀਰਤਾ ਨਾਲ ਇੱਕ ਸਵਾਲ ਪੁੱਛਿਆ, ''ਅਰਜੁਨ! ਜੇ ਇਹ ਮਸ਼ੀਨ ਕਦੇ ਤੈਥੋਂ ਵੱਧ ਤੇਜ਼ ਹੋ ਗਈ, ਤੇਰੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹੋ ਗਈ ਤਾਂ?''$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e2e0d1fc-ecbc-43b7-af8d-83a1fc22c395', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਦੇ ਦਿਲ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਬੀਜ ਗਿਆ। ਉਹ ਨਿਰਉੱਤਰ ਹੋਇਆ ਖੜ੍ਹਾ ਰਿਹਾ। ਘਰ ਆ ਕੇ ਅਰਜੁਨ ਦੇ ਮਨ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਸਤੀਸ਼ ਸਰ ਦਾ ਸਵਾਲ ਘੁੰਮਣ ਲੱਗਾ। ਅਗਲੇ ਦਿਨ ਤੋਂ ਅਰਜੁਨ ਦੀ ਸੋਚ ਦੀ ਦਿਸ਼ਾ ਬਦਲ ਗਈ। ਉਹ ਸਮਾਰਟੋ ਦੇ ਕੰਮਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖਦਾ ਤੇ ਸੋਚਦਾ, ''ਕੀ ਇਹ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਵਧੀਆ ਹੈ ਜਾਂ ਇਸ ਦੇ ਪਿੱਛੇ ਕੋਈ ਖ਼ਤਰਾ ਵੀ ਲੁਕਿਆ ਹੋ ਸਕਦਾ ਹੈ?'' ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਡਾਕਟਰੀ ਖੇਤਰ ਆਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('66f7678b-2086-4c19-a572-ff9508ffd6b1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜ ਬਣਾਉਟੀ ਬੁੱਧੀ (ਏ.ਆਈ.) ਬਿਮਾਰੀਆਂ ਦੀ ਪਹਿਚਾਣ ਉਸ ਸਮੇਂ ਕਰ ਲੈਂਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਨੂੰ ਆਪ ਵੀ ਬਿਮਾਰੀ ਦਾ ਅਹਿਸਾਸ ਨਹੀਂ ਹੁੰਦਾ। ਰੋਬੋਟਿਕ ਸਰਜਰੀਆਂ ਹੋ ਰਹੀਆਂ ਹਨ ਜਿੱਥੇ ਗਲਤੀ ਦੀ ਸੰਭਾਵਨਾ ਘੱਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਜਾਨਾਂ ਬਚ ਰਹੀਆਂ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0c636968-2ce8-4779-a140-8c4dc2a1a884', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਸ ਨੇ ਖੇਤੀਬਾੜੀ ਬਾਰੇ ਸੋਚਿਆ। ਕੈਮਰਿਆਂ ਅਤੇ ਸੈਂਸਰਾਂ ਰਾਹੀਂ ਮਿੱਟੀ ਦੀ ਨਮੀ, ਫਸਲ ਦਾ ਰੰਗ ਅਤੇ ਕੀੜਿਆਂ ਦੀ ਪਹਿਚਾਣ ਕਰਕੇ ਕਿਸਾਨਾਂ ਨੂੰ ਸਮੇਂ ਸਿਰ ਸਲਾਹ ਮਿਲਦੀ ਹੈ। ਇਸ ਨਾਲ ਉਤਪਾਦਨ ਵਧਦਾ ਹੈ ਤੇ ਮਿਹਨਤ ਘੱਟਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('162fa991-41c3-40ce-a003-020f3deab2ce', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਸਿਰਫ਼ ਇੱਕ ਰੋਬੋਟ ਨਹੀਂ ਸੀ— ਉਹ ਇੱਕ ਇਲੈਕਟ੍ਰੋਨਿਕ ਦੋਸਤ, ਅਧਿਆਪਕ, ਸਹਾਇਕ, ਘਰ ਦਾ ਸਫ਼ਾਈ ਕਰਤਾ ਅਤੇ ਪਿਆਰ ਨਾਲ ਗੱਲਾਂ ਕਰਨ ਵਾਲਾ ਸਾਥੀ ਵੀ ਸੀ। ਅਰਜੁਨ ਦਿਨੋ-ਦਿਨ ਉਸ ਉੱਤੇ ਨਿਰਭਰ ਹੋਣ ਲੱਗਾ। ਰੋਜ਼ ਦੀ ਪੜ੍ਹਾਈ, ਘਰੇਲੂ ਕੰਮ-ਕਾਜ, ਸਵਾਲ-ਜਵਾਬ ਸਭ-ਕੁਝ ਉਹ ਸਮਾਰਟੋ ਨਾਲ ਕਰਦਾ। ਹੁਣ ਤਾਂ ਅਰਜੁਨ ਦੇ ਹਰ ਦਿਨ ਦੀ ਸ਼ੁਰੂਆਤ ਸਮਾਰਟੋ ਨਾਲ ਹੁੰਦੀ ਤੇ ਸਮਾਪਤੀ ਵੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('67556627-641b-4359-bee6-e3d0bf48067d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਦਿਨ ਅਰਜੁਨ ਦੇ ਸਕੂਲ ਵਿੱਚ ਵਿਗਿਆਨ ਮੇਲਾ ਲੱਗ ਗਿਆ। ਉਸ ਨੇ ਸੋਚਿਆ ਕਿਉਂ ਨਾ ਸਮਾਰਟੋ ਨੂੰ ਸਕੂਲ ਵਿੱਚ ਲਿਜਾਇਆ ਜਾਵੇ। ਜਦੋਂ ਉਹ ਸਮਾਰਟੋ ਨੂੰ ਮੰਚ ਉੱਤੇ ਲੈ ਕੇ ਗਿਆ ਤਾਂ ਬਾਕੀ ਵਿਦਿਆਰਥੀ ਹੈਰਾਨ ਰਹਿ ਗਏ। ਰੋਬੋਟ ਨਾ ਸਿਰਫ਼ ਸਵਾਲਾਂ ਦੇ ਜਵਾਬ ਤੁਰੰਤ ਹੀ ਦੇ ਰਿਹਾ ਸੀ ਬਲਕਿ ਉਹ ਬਹੁਤ ਚੰਗੇ ਅੰਦਾਜ਼ ਵਿੱਚ ਸਮਝਾ ਵੀ ਰਿਹਾ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('26c0a5a8-47aa-4b3f-b60f-f30939d62106', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਨੇ ਪੁੱਛਿਆ ਮਨੁੱਖ ਨੇ ਚੰਦ ਉੱਤੇ ਕਦਮ ਕਿਵੇਂ ਰੱਖਿਆ? ਸਮਾਰਟੋ ਨੇ ਤੁਰੰਤ ਉੱਤਰ ਦੇ ਕੇ ਨੀਲ ਆਰਮਸਟ੍ਰਾਂਗ ਦੇ ਚੰਨ ਉੱਤੇ ਪੈਰ ਰੱਖਣ ਦੀ ਤਸਵੀਰ ਸਕਰੀਨ ਉੱਤੇ ਸਾਂਝੀ ਕਰ ਦਿੱਤੀ। ਸਕੂਲ ਦਾ ਮਾਹੌਲ ਤਾੜੀਆਂ ਨਾਲ ਗੂੰਜ ਉੱਠਿਆ। ਪਰ ਸਤੀਸ਼ ਸਰ ਨੇ ਗੰਭੀਰਤਾ ਨਾਲ ਇੱਕ ਸਵਾਲ ਪੁੱਛਿਆ, ''ਅਰਜੁਨ! ਜੇ ਇਹ ਮਸ਼ੀਨ ਕਦੇ ਤੈਥੋਂ ਵੱਧ ਤੇਜ਼ ਹੋ ਗਈ, ਤੇਰੇ ਕੰਟਰੋਲ ਤੋਂ ਬਾਹਰ ਹੋ ਗਈ ਤਾਂ?''$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d152d95f-9682-4dd8-9e99-0cfd77742ca0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਦੇ ਦਿਲ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਬੀਜ ਗਿਆ। ਉਹ ਨਿਰਉੱਤਰ ਹੋਇਆ ਖੜ੍ਹਾ ਰਿਹਾ। ਘਰ ਆ ਕੇ ਅਰਜੁਨ ਦੇ ਮਨ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਸਤੀਸ਼ ਸਰ ਦਾ ਸਵਾਲ ਘੁੰਮਣ ਲੱਗਾ। ਅਗਲੇ ਦਿਨ ਤੋਂ ਅਰਜੁਨ ਦੀ ਸੋਚ ਦੀ ਦਿਸ਼ਾ ਬਦਲ ਗਈ। ਉਹ ਸਮਾਰਟੋ ਦੇ ਕੰਮਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖਦਾ ਤੇ ਸੋਚਦਾ, ''ਕੀ ਇਹ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਵਧੀਆ ਹੈ ਜਾਂ ਇਸ ਦੇ ਪਿੱਛੇ ਕੋਈ ਖ਼ਤਰਾ ਵੀ ਲੁਕਿਆ ਹੋ ਸਕਦਾ ਹੈ?'' ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਡਾਕਟਰੀ ਖੇਤਰ ਆਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1bfe30f4-497c-4c6f-82fc-6223d20009b8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਜ ਬਣਾਉਟੀ ਬੁੱਧੀ (ਏ.ਆਈ.) ਬਿਮਾਰੀਆਂ ਦੀ ਪਹਿਚਾਣ ਉਸ ਸਮੇਂ ਕਰ ਲੈਂਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਨੂੰ ਆਪ ਵੀ ਬਿਮਾਰੀ ਦਾ ਅਹਿਸਾਸ ਨਹੀਂ ਹੁੰਦਾ। ਰੋਬੋਟਿਕ ਸਰਜਰੀਆਂ ਹੋ ਰਹੀਆਂ ਹਨ ਜਿੱਥੇ ਗਲਤੀ ਦੀ ਸੰਭਾਵਨਾ ਘੱਟਦੀ ਹੈ। ਇਸ ਨਾਲ ਮਨੁੱਖੀ ਜਾਨਾਂ ਬਚ ਰਹੀਆਂ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3a1db070-4383-461b-ac1b-863c01f39758', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਸ ਨੇ ਖੇਤੀਬਾੜੀ ਬਾਰੇ ਸੋਚਿਆ। ਕੈਮਰਿਆਂ ਅਤੇ ਸੈਂਸਰਾਂ ਰਾਹੀਂ ਮਿੱਟੀ ਦੀ ਨਮੀ, ਫਸਲ ਦਾ ਰੰਗ ਅਤੇ ਕੀੜਿਆਂ ਦੀ ਪਹਿਚਾਣ ਕਰਕੇ ਕਿਸਾਨਾਂ ਨੂੰ ਸਮੇਂ ਸਿਰ ਸਲਾਹ ਮਿਲਦੀ ਹੈ। ਇਸ ਨਾਲ ਉਤਪਾਦਨ ਵਧਦਾ ਹੈ ਤੇ ਮਿਹਨਤ ਘੱਟਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('35c5b3b9-c2ce-4e0b-9a19-76064840cc01', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7b0fdaeb-f1b7-4759-b725-dfc958e65ab8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('6eb73c16-3dbe-41bf-87fe-20390d8e83cd', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ। ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('46182d3b-512b-4c0a-b33e-d66303fc9382', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d07a0976-7bba-432c-aece-b98f27b842b7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜੀ ਚੁਣੌਤੀ ਸੁਰੱਖਿਆ ਦੀ ਸੀ। ਜੇ ਏ.ਆਈ. ਹਥਿਆਰਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਤਾਂ ਜੰਗਾਂ ਹੋਰ ਵੀ ਖੂਨੀ ਤੇ ਵਿਨਾਸ਼ਕਾਰੀ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸੋਚੋ, ਜੇ ਬਿਨਾਂ ਮਨੁੱਖੀ ਦਖਲ ਦੇ ਹੀ ਰੋਬੋਟ ਫੌਜ ਲੜਾਈ ਲੜਨ ਲੱਗੇ ਤਾਂ ਨਤੀਜੇ ਕਿੰਨੇ ਖਤਰਨਾਕ ਹੋਣਗੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c88c38d8-9a28-44b2-9f64-611e58634c89', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ ਖਤਰਾ ਨੈਤਿਕਤਾ ਨਾਲ ਸੀ। (ਏ.ਆਈ.) ਦੇ ਕੋਲ ਦਿਲ ਨਹੀਂ ਹੁੰਦਾ। ਉਹ ਫੈਸਲੇ ਸਿਰਫ ਡਾਟਾ ਦੇ ਆਧਾਰ ਉੱਤੇ ਕਰਦੀ ਹੈ ਪਰ ਮਨੁੱਖੀ ਜੀਵਨ ਸਿਰਫ ਅੰਕੜਿਆਂ ਨਾਲ ਨਹੀਂ, ਭਾਵਨਾਵਾਂ ਨਾਲ ਵੀ ਚੱਲਦਾ ਹੈ। ਜੇ ਕੋਈ ਰੋਬੋਟ ਜੱਜ ਬਣ ਜਾਵੇ ਤਾਂ ਕੀ ਉਹ ਇਨਸਾਫ ਕਰ ਸਕੇਗਾ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3992da87-a8db-44d5-8025-f34aa398afa2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fc8e3e5b-35aa-4c9a-bbf0-35edc89792b4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('79c346fc-87b2-42d1-a0ca-f3a396485f09', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a54a3eef-4bfc-4297-9f48-aed5b4818d5d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ। ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('6f58cb39-8884-4746-b5a9-95873a468a54', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ। ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ। ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ। ਦੂਜੀ ਚੁਣੌਤੀ ਸੁਰੱਖਿਆ ਦੀ ਸੀ। ਜੇ ਏ.ਆਈ. ਹਥਿਆਰਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਤਾਂ ਜੰਗਾਂ ਹੋਰ ਵੀ ਖੂਨੀ ਤੇ ਵਿਨਾਸ਼ਕਾਰੀ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸੋਚੋ, ਜੇ ਬਿਨਾਂ ਮਨੁੱਖੀ ਦਖਲ ਦੇ ਹੀ ਰੋਬੋਟ ਫੌਜ ਲੜਾਈ ਲੜਨ ਲੱਗੇ ਤਾਂ ਨਤੀਜੇ ਕਿੰਨੇ ਖਤਰਨਾਕ ਹੋਣਗੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d9e1eebf-33ba-4863-a44d-73ad6e6a7fcb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ ਖਤਰਾ ਨੈਤਿਕਤਾ ਨਾਲ ਸੀ। (ਏ.ਆਈ.) ਦੇ ਕੋਲ ਦਿਲ ਨਹੀਂ ਹੁੰਦਾ। ਉਹ ਫੈਸਲੇ ਸਿਰਫ ਡਾਟਾ ਦੇ ਆਧਾਰ ਉੱਤੇ ਕਰਦੀ ਹੈ ਪਰ ਮਨੁੱਖੀ ਜੀਵਨ ਸਿਰਫ ਅੰਕੜਿਆਂ ਨਾਲ ਨਹੀਂ, ਭਾਵਨਾਵਾਂ ਨਾਲ ਵੀ ਚੱਲਦਾ ਹੈ। ਜੇ ਕੋਈ ਰੋਬੋਟ ਜੱਜ ਬਣ ਜਾਵੇ ਤਾਂ ਕੀ ਉਹ ਇਨਸਾਫ ਕਰ ਸਕੇਗਾ? ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e4f5a823-5005-48b5-83dc-c84cef893ce4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?' ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('405385cb-a714-4038-b27a-67ee4efcd21c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਿਆ ਦੇ ਖੇਤਰ ਵਿੱਚ ਵੀ (ਏ.ਆਈ.) ਨੇ ਕਮਾਲ ਕਰ ਦਿੱਤਾ ਹੈ। ਹੁਣ ਬੱਚੇ ਆਪਣੇ ਨਿੱਜੀ (ਏ.ਆਈ.) ਟਿਊਟਰਾਂ ਤੋਂ ਪੜ੍ਹ ਰਹੇ ਹਨ। ਹਰ ਵਿਦਿਆਰਥੀ ਦੇ ਪੱਧਰ ਮੁਤਾਬਕ ਪਾਠ ਤਿਆਰ ਹੁੰਦੇ ਹਨ। ਅਰਜੁਨ ਸੋਚਦਾ ਸੀ ਜਿਵੇਂ ਸਮਾਰਟੋ ਮੇਰਾ ਸਾਥੀ ਹੈ, ਇੰਝ ਹੀ ਹਰ ਬੱਚੇ ਨੂੰ ਇੱਕ ਸਿਆਣਾ ਦੋਸਤ ਮਿਲ ਜਾਵੇ ਤਾਂ ਸਿੱਖਣ ਦਾ ਆਨੰਦ ਕਿੰਨਾ ਵੱਧ ਜਾਵੇਗਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('05bd69b8-8ad1-486c-8c3d-0335f6b18512', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰ ਗ੍ਰਹਿਸਥੀ ਵਿੱਚ ਵੀ ਰੋਬੋਟ ਮਦਦਗਾਰ ਸਾਬਤ ਹੋ ਰਹੇ ਹਨ। ਘਰ ਦੇ ਹਰ ਕੰਮ ਜਿਵੇਂ ਰਸੋਈ ਦੀ ਸਫਾਈ, ਬਜ਼ੁਰਗਾਂ ਦੀ ਦੇਖਭਾਲ ਤੇ ਹੋਰ ਕੰਮ ਪਲਾਂ ਛਿਣਾਂ ਵਿੱਚ ਹੀ ਕਰ ਦਿੰਦੇ ਹਨ। ਕਾਰਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਚਲਾਉਣ ਯੋਗ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e9d94f02-97b8-42c6-b5b5-d44375f9fe66', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਭ ਦੇਖ ਕੇ ਅਰਜੁਨ ਨੂੰ ਭਵਿੱਖ ਬੜਾ ਚਮਕਦਾਰ ਨਜ਼ਰ ਆਇਆ। ਪਰ ਅਚਾਨਕ ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਸੰਦੇਹ ਦਾ ਦੂਜਾ ਪਾਸਾ ਪਲਟਿਆ। ਇਸ ਪਾਸੇ ਵੱਲ ਸਮਾਰਟੋ ਨਾਲ ਵੱਡੀਆਂ ਚਿੰਤਾਵਾਂ ਖੜ੍ਹੀਆਂ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('31ed2662-ab0a-4ea0-ad21-7bdd2e687fca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਭ ਤੋਂ ਪਹਿਲਾ ਸਵਾਲ ਨੌਕਰੀਆਂ ਦਾ ਸੀ। ਜੇ ਹਰ ਕੰਮ ਮਸ਼ੀਨ ਕਰਨ ਲੱਗ ਪਈ ਤਾਂ ਮਨੁੱਖੀ ਮਿਹਨਤ ਦੀ ਕੀ ਲੋੜ ਰਹਿ ਜਾਵੇਗੀ? ਪਹਿਲਾਂ ਹੀ ਕਈ ਫੈਕਟਰੀਆਂ ਵਿੱਚ ਰੋਬੋਟਾਂ ਨੇ ਮਜ਼ਦੂਰਾਂ ਦੀ ਥਾਂ ਲੈ ਲਈ ਹੈ। ਇਹ ਹਾਲਾਤ ਬੇਰੁਜ਼ਗਾਰੀ ਨੂੰ ਜਨਮ ਦੇ ਸਕਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ca7cd7b4-a9a6-499c-b92d-a832857440be', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜੀ ਚੁਣੌਤੀ ਸੁਰੱਖਿਆ ਦੀ ਸੀ। ਜੇ ਏ.ਆਈ. ਹਥਿਆਰਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਤਾਂ ਜੰਗਾਂ ਹੋਰ ਵੀ ਖੂਨੀ ਤੇ ਵਿਨਾਸ਼ਕਾਰੀ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸੋਚੋ, ਜੇ ਬਿਨਾਂ ਮਨੁੱਖੀ ਦਖਲ ਦੇ ਹੀ ਰੋਬੋਟ ਫੌਜ ਲੜਾਈ ਲੜਨ ਲੱਗੇ ਤਾਂ ਨਤੀਜੇ ਕਿੰਨੇ ਖਤਰਨਾਕ ਹੋਣਗੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fd21689a-001d-4b7a-8f26-d78638240fe7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜਾ ਖਤਰਾ ਨੈਤਿਕਤਾ ਨਾਲ ਸੀ। (ਏ.ਆਈ.) ਦੇ ਕੋਲ ਦਿਲ ਨਹੀਂ ਹੁੰਦਾ। ਉਹ ਫੈਸਲੇ ਸਿਰਫ ਡਾਟਾ ਦੇ ਆਧਾਰ ਉੱਤੇ ਕਰਦੀ ਹੈ ਪਰ ਮਨੁੱਖੀ ਜੀਵਨ ਸਿਰਫ ਅੰਕੜਿਆਂ ਨਾਲ ਨਹੀਂ, ਭਾਵਨਾਵਾਂ ਨਾਲ ਵੀ ਚੱਲਦਾ ਹੈ। ਜੇ ਕੋਈ ਰੋਬੋਟ ਜੱਜ ਬਣ ਜਾਵੇ ਤਾਂ ਕੀ ਉਹ ਇਨਸਾਫ ਕਰ ਸਕੇਗਾ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('221b97dd-4037-4f6f-896b-af9b5f388c71', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸਵਾਲ ਅਰਜੁਨ ਨੂੰ ਹੋਰ ਅਸਹਿਜ ਕਰ ਗਏ। ਉਸ ਨੇ ਆਪਣੇ-ਆਪ ਨੂੰ ਭਵਿੱਖ ਦੇ ਇੱਕ ਆਧੁਨਿਕ ਸ਼ਹਿਰ ਵਿੱਚ ਵੇਖਿਆ। ਹਰ ਪਾਸੇ ਰੋਬੋਟ, ਡਰੋਨ, ਆਟੋਮੈਟਿਕ ਕਾਰਾਂ, ਰੋਬੋਟ ਡਾਕਟਰ, ਏ.ਆਈ. ਅਧਿਆਪਕ, ਆਟੋਮੈਟਿਕ ਘਰ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3e2accfd-299f-466f-a038-1bef45ca924a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਥੋੜ੍ਹੀ ਦੂਰ ਇੱਕ ਗਲੀ ਵਿੱਚ ਉਸ ਨੇ ਕੁਝ ਮਨੁੱਖੀ ਚਿਹਰੇ ਬਿਨਾਂ ਕਿਸੇ ਚਮਕ ਤੋਂ ਘੋਰ ਉਦਾਸੀ ਵਿੱਚ ਵੇਖੇ। ਮਿਹਨਤ ਵਾਲੇ ਹੱਥ ਲਾਚਾਰ ਸਨ। ਅਰਜੁਨ ਨੇ ਪੁੱਛਿਆ, 'ਸਮਾਰਟੋ! ਇਹ ਕਿਉਂ ਹੋ ਰਿਹਾ ਹੈ?'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('bcc4ba9d-3be4-4b5e-8c53-5b8b4580b08b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਮਾਰਟੋ ਨੇ ਕਿਹਾ, 'ਮੈਂ ਸਿਰਫ ਸਾਧਨ ਹਾਂ, ਮਾਲਕ ਤੂੰ ਹੈਂ। ਜੇ ਤੂੰ ਮੈਨੂੰ ਸਿਆਣਪ ਨਾਲ ਵਰਤੇਂਗਾ ਤਾਂ ਮੈਂ ਤੇਰਾ ਦੋਸਤ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਤੇਰਾ ਵੈਰੀ ਵੀ ਬਣ ਸਕਦਾ ਹਾਂ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b7dfebd9-fe0d-4eb7-9545-347b9d7202af', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਇੱਕਦਮ ਅੱਭੜਵਾਹੇ ਬੋਲ ਪਿਆ, 'ਇਨਸਾਨ ਦੇ ਦਿਮਾਗ ਦੀ ਥਾਂ ਕੋਈ ਨਹੀਂ ਲੈ ਸਕਦਾ। ਬਣਾਉਟੀ ਬੁੱਧੀ ਇੱਕ ਦੋਧਾਰੀ ਤਲਵਾਰ ਹੈ। ਇਸ ਦੀ ਸਹੀ ਵਰਤੋਂ ਮਨੁੱਖਤਾ ਨੂੰ ਨਵੀਆਂ ਉਚਾਈਆਂ ਤੱਕ ਲੈ ਜਾ ਸਕਦੀ ਹੈ ਪਰ ਗਲਤ ਵਰਤੋਂ ਵਿਨਾਸ਼ਕਾਰੀ ਦਾ ਕਾਰਨ ਬਣ ਸਕਦੀ ਹੈ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('560f9177-b0a3-4cd3-a5ac-c194edb5cdea', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਬਹੁਤ ਸੋਚ-ਵਿਚਾਰ ਤੋਂ ਬਾਅਦ ਆਪਣੀ ਡਾਇਰੀ ਖੋਲ੍ਹ ਕੇ ਉਸ ਵਿੱਚ ਲਿਖਿਆ- ਬਣਾਉਟੀ ਬੁੱਧੀ ਮਨੁੱਖ ਦਾ ਭਵਿੱਖ ਹੈ। ਪਰ ਇਹ ਭਵਿੱਖ ਉੱਜਲਾ ਜਾਂ ਹਨੇਰਾ ਰਹੇਗਾ, ਇਹ ਮਨੁੱਖ ਦੀ ਸੋਚ, ਨੈਤਿਕਤਾ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀ 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('22ba092e-200c-43aa-85de-ca79c24505ba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਕੂਲ ਦੀ ਅਸੈਂਬਲੀ ਵਿੱਚ ਅਰਜੁਨ ਨੇ ਆਪਣਾ ਅਨੁਭਵ ਸਾਂਝਾ ਕੀਤਾ। ਉਸ ਨੇ ਕਿਹਾ, 'ਅਸੀਂ ਤਕਨੀਕ ਨੂੰ ਆਪਣੇ ਹਥਿਆਰ ਨਹੀਂ, ਆਪਣਾ ਸਾਥੀ ਬਣਾਵਾਂਗੇ।' ਅਧਿਆਪਕ, ਵਿਦਿਆਰਥੀ, ਪ੍ਰਿੰਸੀਪਲ ਸਭ ਉਸ ਦੀ ਸੋਚ 'ਤੇ ਮਾਣ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1f87758f-06cf-4da3-8070-683339448c93', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ 'ਤੇ ਆਧਾਰਿਤ) * ਨਵੀਂ ਤਕਨੀਕ ਸਿੱਖਣ ਵਿੱਚ ਰੁਚੀ ਪੈਦਾ ਹੋਣਾ। * ਤਕਨੀਕ ਦੀ ਵਰਤੋਂ ਚੰਗੇ-ਮਾੜੇ ਪੱਖਾਂ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਣੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2a714c47-8b16-4ba2-b61a-a28dc8db72a3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੋਚੋ ਤੇ ਪ੍ਰਗਟਾਓ: A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ— (ੳ) ਤੁਹਾਡੇ ਵਿਚਾਰ ਅਨੁਸਾਰ ਜੇਕਰ ਹਰੇਕ ਘਰ ਵਿੱਚ ਇੱਕ ਰੋਬੋਟ ਹੋਵੇ ਤਾਂ ਕੀ ਹੋਵੇਗਾ? (ਅ) ਕੀ ਰੋਬੋਟ ਅਧਿਆਪਕ ਮਨੁੱਖੀ ਅਧਿਆਪਕ ਦੀ ਥਾਂ ਲੈ ਸਕਦੇ ਹਨ? ਕਿਉਂ? (ੲ) ਜੇ ਤੁਹਾਨੂੰ ਮੌਕਾ ਮਿਲੇ ਤਾਂ ਤੁਸੀਂ ਕਿਹੜਾ ਕੰਮ ਰੋਬੋਟ ਤੋਂ ਕਰਵਾਉਣਾ ਚਾਹੋਗੇ ਅਤੇ ਕਿਉਂ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('79d1d451-5a65-499a-8fe8-d3bf8063a7dc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅੱਭੜਵਾਹੇ - ਇੱਕਦਮ, ਦੋਧਾਰੀ ਤਲਵਾਰ - ਜਿਸ ਦੇ ਚੰਗੇ-ਮਾੜੇ ਦੋਵੇਂ ਨਤੀਜੇ ਹੋ ਸਕਣ, ਵਿਨਾਸ਼ਕਾਰੀ - ਤਬਾਹੀ ਲਿਆਉਣ ਵਾਲਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('df5b0c3d-af3f-4f7a-965a-e08805edd45d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਇੱਕਦਮ ਅੱਭੜਵਾਹੇ ਬੋਲ ਪਿਆ, 'ਇਨਸਾਨ ਦੇ ਦਿਮਾਗ ਦੀ ਥਾਂ ਕੋਈ ਨਹੀਂ ਲੈ ਸਕਦਾ। ਬਣਾਉਟੀ ਬੁੱਧੀ ਇੱਕ ਦੋਧਾਰੀ ਤਲਵਾਰ ਹੈ।' ਉਸ ਨੇ ਬਹੁਤ ਸੋਚ-ਵਿਚਾਰ ਤੋਂ ਬਾਅਦ ਆਪਣੀ ਡਾਇਰੀ ਖੋਲ੍ਹ ਕੇ ਉਸ ਵਿੱਚ ਲਿਖਿਆ- ਬਣਾਉਟੀ ਬੁੱਧੀ ਮਨੁੱਖ ਦਾ ਭਵਿੱਖ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('89a8d91a-cc9c-4f4d-b73b-72a351b5fca9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਣਾਉਟੀ ਬੁੱਧੀ ਇੱਕ ਦੋਧਾਰੀ ਤਲਵਾਰ ਹੈ। ਇਸ ਦੀ ਸਹੀ ਵਰਤੋਂ ਮਨੁੱਖਤਾ ਨੂੰ ਨਵੀਆਂ ਉਚਾਈਆਂ ਤੱਕ ਲੈ ਜਾ ਸਕਦੀ ਹੈ ਪਰ ਗਲਤ ਵਰਤੋਂ ਵਿਨਾਸ਼ਕਾਰੀ ਦਾ ਕਾਰਨ ਬਣ ਸਕਦੀ ਹੈ। ਪਰ ਇਹ ਭਵਿੱਖ ਉੱਜਲਾ ਜਾਂ ਹਨੇਰਾ ਰਹੇਗਾ, ਇਹ ਮਨੁੱਖ ਦੀ ਸੋਚ, ਨੈਤਿਕਤਾ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀ 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('afa39595-1dae-4659-ae70-b04dd46118b8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਕੂਲ ਦੀ ਅਸੈਂਬਲੀ ਵਿੱਚ ਅਰਜੁਨ ਨੇ ਆਪਣਾ ਅਨੁਭਵ ਸਾਂਝਾ ਕੀਤਾ। ਉਸ ਨੇ ਕਿਹਾ, 'ਅਸੀਂ ਤਕਨੀਕ ਨੂੰ ਆਪਣੇ ਹਥਿਆਰ ਨਹੀਂ, ਆਪਣਾ ਸਾਥੀ ਬਣਾਵਾਂਗੇ।' ਅਧਿਆਪਕ, ਵਿਦਿਆਰਥੀ, ਪ੍ਰਿੰਸੀਪਲ ਸਭ ਉਸ ਦੀ ਸੋਚ 'ਤੇ ਮਾਣ ਕਰ ਰਹੇ ਸਨ। ਸਿੱਖਣ ਨਤੀਜੇ: ਨਵੀਂ ਤਕਨੀਕ ਸਿੱਖਣ ਵਿੱਚ ਰੁਚੀ ਪੈਦਾ ਹੋਣਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9b96977a-a480-4992-bfbe-23cfe09d0441', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ 'ਤੇ ਆਧਾਰਿਤ) * ਨਵੀਂ ਤਕਨੀਕ ਸਿੱਖਣ ਵਿੱਚ ਰੁਚੀ ਪੈਦਾ ਹੋਣਾ। * ਤਕਨੀਕ ਦੀ ਵਰਤੋਂ ਚੰਗੇ-ਮਾੜੇ ਪੱਖਾਂ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਣੀ। (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ—$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('167b60bd-03a8-47c1-8742-1cf620c088ce', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੁਹਾਡੇ ਵਿਚਾਰ ਅਨੁਸਾਰ ਜੇਕਰ ਹਰੇਕ ਘਰ ਵਿੱਚ ਇੱਕ ਰੋਬੋਟ ਹੋਵੇ ਤਾਂ ਕੀ ਹੋਵੇਗਾ? ਕੀ ਰੋਬੋਟ ਅਧਿਆਪਕ ਮਨੁੱਖੀ ਅਧਿਆਪਕ ਦੀ ਥਾਂ ਲੈ ਸਕਦੇ ਹਨ? ਕਿਉਂ? ਜੇ ਤੁਹਾਨੂੰ ਮੌਕਾ ਮਿਲੇ ਤਾਂ ਤੁਸੀਂ ਕਿਹੜਾ ਕੰਮ ਰੋਬੋਟ ਤੋਂ ਕਰਵਾਉਣਾ ਚਾਹੋਗੇ ਅਤੇ ਕਿਉਂ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
