  ('decaedca-7dd7-4d3d-9874-4dc441791a72', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਣਾਉਟੀ ਬੁੱਧੀ ਮਨੁੱਖ ਦਾ ਭਵਿੱਖ ਹੈ। ਪਰ ਇਹ ਭਵਿੱਖ ਉੱਜਲਾ ਜਾਂ ਹਨੇਰਾ ਰਹੇਗਾ, ਇਹ ਮਨੁੱਖ ਦੀ ਸੋਚ, ਨੈਤਿਕਤਾ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀ 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7b1752df-3eb3-4c3c-8533-fc129d137d6a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਕੂਲ ਦੀ ਅਸੈਂਬਲੀ ਵਿੱਚ ਅਰਜੁਨ ਨੇ ਆਪਣਾ ਅਨੁਭਵ ਸਾਂਝਾ ਕੀਤਾ। ਉਸ ਨੇ ਕਿਹਾ, 'ਅਸੀਂ ਤਕਨੀਕ ਨੂੰ ਆਪਣੇ ਹਥਿਆਰ ਨਹੀਂ, ਆਪਣਾ ਸਾਥੀ ਬਣਾਵਾਂਗੇ।' ਅਧਿਆਪਕ, ਵਿਦਿਆਰਥੀ, ਪ੍ਰਿੰਸੀਪਲ ਸਭ ਉਸ ਦੀ ਸੋਚ 'ਤੇ ਮਾਣ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b22a95bc-f7ac-4118-91bb-75f195fc0647', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes): ਨਵੀਂ ਤਕਨੀਕ ਸਿੱਖਣ ਵਿੱਚ ਰੁਚੀ ਪੈਦਾ ਹੋਣਾ। ਤਕਨੀਕ ਦੀ ਵਰਤੋਂ ਚੰਗੇ-ਮਾੜੇ ਪੱਖਾਂ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਣੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cb7ab04e-877b-4240-94f2-0ba8672c6dd3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ 'ਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ— (ੳ) ਤੁਹਾਡੇ ਵਿਚਾਰ ਅਨੁਸਾਰ ਜੇਕਰ ਹਰੇਕ ਘਰ ਵਿੱਚ ਇੱਕ ਰੋਬੋਟ ਹੋਵੇ ਤਾਂ ਕੀ ਹੋਵੇਗਾ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('919613ce-5dc8-4651-975a-98bb24e73b8b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਅ) ਕੀ ਰੋਬੋਟ ਅਧਿਆਪਕ ਮਨੁੱਖੀ ਅਧਿਆਪਕ ਦੀ ਥਾਂ ਲੈ ਸਕਦੇ ਹਨ? ਕਿਉਂ? (ੲ) ਜੇ ਤੁਹਾਨੂੰ ਮੌਕਾ ਮਿਲੇ ਤਾਂ ਤੁਸੀਂ ਕਿਹੜਾ ਕੰਮ ਰੋਬੋਟ ਤੋਂ ਕਰਵਾਉਣਾ ਚਾਹੋਗੇ ਅਤੇ ਕਿਉਂ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
