  ('3efede2e-fc33-40fa-97bf-e13c69d04e1b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਕੂਲ ਦੀ ਅਸੈਂਬਲੀ ਵਿੱਚ ਅਰਜੁਨ ਨੇ ਆਪਣਾ ਅਨੁਭਵ ਸਾਂਝਾ ਕੀਤਾ। ਉਸ ਨੇ ਕਿਹਾ, 'ਅਸੀਂ ਤਕਨੀਕ ਨੂੰ ਆਪਣੇ ਹਥਿਆਰ ਨਹੀਂ, ਆਪਣਾ ਸਾਥੀ ਬਣਾਵਾਂਗੇ।' ਅਧਿਆਪਕ, ਵਿਦਿਆਰਥੀ, ਪ੍ਰਿੰਸੀਪਲ ਸਭ ਉਸ ਦੀ ਸੋਚ 'ਤੇ ਮਾਣ ਕਰ ਰਹੇ ਸਨ। ਸਿੱਖਣ ਨਤੀਜੇ: ਨਵੀਂ ਤਕਨੀਕ ਸਿੱਖਣ ਵਿੱਚ ਰੁਚੀ ਪੈਦਾ ਹੋਣਾ। ਤਕਨੀਕ ਦੀ ਵਰਤੋਂ ਚੰਗੇ-ਮਾੜੇ ਪੱਖਾਂ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਣੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fee07658-8d5f-4d7f-9fe3-9220a9b272c0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ 'ਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ— (ੳ) ਤੁਹਾਡੇ ਵਿਚਾਰ ਅਨੁਸਾਰ ਜੇਕਰ ਹਰੇਕ ਘਰ ਵਿੱਚ ਇੱਕ ਰੋਬੋਟ ਹੋਵੇ ਤਾਂ ਕੀ ਹੋਵੇਗਾ? (ਅ) ਕੀ ਰੋਬੋਟ ਅਧਿਆਪਕ ਮਨੁੱਖੀ ਅਧਿਆਪਕ ਦੀ ਥਾਂ ਲੈ ਸਕਦੇ ਹਨ? ਕਿਉਂ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0162fb9d-5e84-4bdd-b165-0de55e928788', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਰਜੁਨ ਇੱਕਦਮ ਅੱਭੜਵਾਹੇ ਬੋਲ ਪਿਆ, 'ਇਨਸਾਨ ਦੇ ਦਿਮਾਗ ਦੀ ਥਾਂ ਕੋਈ ਨਹੀਂ ਲੈ ਸਕਦਾ। ਬਣਾਉਟੀ ਬੁੱਧੀ ਇੱਕ ਦੋਧਾਰੀ ਤਲਵਾਰ ਹੈ। ਇਸ ਦੀ ਸਹੀ ਵਰਤੋਂ ਮਨੁੱਖਤਾ ਨੂੰ ਨਵੀਆਂ ਉਚਾਈਆਂ ਤੱਕ ਲੈ ਜਾ ਸਕਦੀ ਹੈ ਪਰ ਗਲਤ ਵਰਤੋਂ ਵਿਨਾਸ਼ਕਾਰੀ ਦਾ ਕਾਰਨ ਬਣ ਸਕਦੀ ਹੈ।' ਅੱਭੜਵਾਹੇ - ਇੱਕਦਮ, ਦੋਧਾਰੀ ਤਲਵਾਰ - ਜਿਸ ਦੇ ਚੰਗੇ-ਮਾੜੇ ਦੋਵੇਂ ਨਤੀਜੇ ਹੋ ਸਕਣ, ਵਿਨਾਸ਼ਕਾਰੀ - ਤਬਾਹੀ ਲਿਆਉਣ ਵਾਲਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ee30d1c9-8443-48ab-9a27-62663e6b9356', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '0c6f8654-d050-41ad-b7b9-cad9618b52b3', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਬਹੁਤ ਸੋਚ-ਵਿਚਾਰ ਤੋਂ ਬਾਅਦ ਆਪਣੀ ਡਾਇਰੀ ਖੋਲ੍ਹ ਕੇ ਉਸ ਵਿੱਚ ਲਿਖਿਆ- ਬਣਾਉਟੀ ਬੁੱਧੀ ਮਨੁੱਖ ਦਾ ਭਵਿੱਖ ਹੈ। ਪਰ ਇਹ ਭਵਿੱਖ ਉੱਜਲਾ ਜਾਂ ਹਨੇਰਾ ਰਹੇਗਾ, ਇਹ ਮਨੁੱਖ ਦੀ ਸੋਚ, ਨੈਤਿਕਤਾ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀ 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ। ਅਧਿਆਪਕ, ਵਿਦਿਆਰਥੀ, ਪ੍ਰਿੰਸੀਪਲ ਸਭ ਉਸ ਦੀ ਸੋਚ 'ਤੇ ਮਾਣ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-238Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL);
